    {"name": "edit", "arguments": {"path": "src/queue.js", "range": "1tx-81wi", "new": "// The queue. README.md has the contract.\n\nimport { CancelledError, TaskTimeoutError } from './errors.js';\n\nexport class JobQueue {\n  constructor({ concurrency = 1 } = {}) { this._validateConcurrency(concurrency); this._concurrency = concurrency; this._running = 0; this._waiting = []; this._paused = false; this._idle = []; }\n  _validateConcurrency(value) { if (!Number.isInteger(value) || value <= 0) throw new RangeError('concurrency must be a positive integer'); }\n  get concurrency() { return this._concurrency; }\n  set concurrency(value) { this._validateConcurrency(value); this._concurrency = value; this._next(); }\n  get pending() { return this._running; }\n  get size() { return this._waiting.length; }\n  get isPaused() { return this._paused; }\n  add(fn, { priority = 0, timeout = 0, retries = 0, retryDelay = 0 } = {}) { return new Promise((resolve, reject) => { const job = { fn, priority, timeout, retries, retryDelay, resolve, reject }; let index = this._waiting.findIndex((other) => other.priority < priority); if (index < 0) index = this._waiting.length; this._waiting.splice(index, 0, job); this._next(); }); }\n  _next() { if (this._paused || this._running >= this._concurrency) return; const job = this._waiting.shift(); if (!job) { if (this._running === 0) for (const resolve of this._idle.splice(0)) resolve(); return; } this._running++; this._run(job, 1).then(job.resolve, job.reject).finally(() => { this._running--; this._next(); }); }\n  async _run(job, attempt) { const controller = new AbortController(); let timer; try { const result = Promise.resolve().then(() => job.fn({ signal: controller.signal, attempt })); if (job.timeout > 0) { const timeout = new Promise((_, reject) => { timer = setTimeout(() => { controller.abort(); reject(new TaskTimeoutError(job.timeout)); }, job.timeout); }); return await Promise.race([result, timeout]); } return await result; } catch (error) { if (attempt <= job.retries) { if (job.retryDelay > 0) await new Promise((resolve) => setTimeout(resolve, job.retryDelay)); return this._run(job, attempt + 1); } throw error; } finally { if (timer) clearTimeout(timer); } }\n  pause() { this._paused = true; }\n  resume() { this._paused = false; this._next(); }\n  clear() { const jobs = this._waiting.splice(0); for (const job of jobs) job.reject(new CancelledError()); return jobs.length; }\n  onIdle() { if (this._running === 0 && this._waiting.length === 0) return Promise.resolve(); return new Promise((resolve) => this._idle.push(resolve)); }\n}"}},
